sql_joins = [
    # Joins & Set Operations (60 Qs)
    ("What is a JOIN in SQL and why is it used?", "A JOIN is an SQL clause used to combine rows from two or more tables based on a related column between them (typically foreign key = primary key).", "Easy", "Concept", "SELECT e.name, d.department_name\nFROM employees e\nINNER JOIN departments d ON e.dept_id = d.id;", "What are the main types of joins?"),
    ("What are the 4 fundamental types of SQL joins?", "1. INNER JOIN (matches in both). 2. LEFT (OUTER) JOIN (all from left + matched right). 3. RIGHT (OUTER) JOIN (all from right + matched left). 4. FULL (OUTER) JOIN (all from both).", "Easy", "Concept", "", "What is the difference between INNER JOIN and LEFT JOIN?"),
    ("What is the difference between INNER JOIN and LEFT JOIN?", "INNER JOIN returns only rows where there is a matching value in BOTH tables. LEFT JOIN returns all rows from the left table, filling with NULL where no match exists on the right.", "Easy", "Comparison", "", "What does a RIGHT JOIN do?"),
    ("What is a RIGHT JOIN?", "RIGHT JOIN returns all rows from the right table, and matched rows from the left table. If there is no match on the left, NULL values are returned.", "Easy", "Concept", "SELECT * FROM orders o RIGHT JOIN customers c ON o.customer_id = c.id;", "Can every RIGHT JOIN be rewritten as a LEFT JOIN?"),
    ("Can every RIGHT JOIN be converted into a LEFT JOIN?", "Yes! Simply swap the table order: 'A RIGHT JOIN B' is identical to 'B LEFT JOIN A'. Most developers standardize on LEFT JOIN for readability.", "Easy", "Best Practice", "", "What is a FULL OUTER JOIN?"),
    ("What is a FULL OUTER JOIN in SQL?", "FULL OUTER JOIN returns all rows when there is a match in either left or right table. If there is no match, the missing side contains NULL.", "Intermediate", "Concept", "SELECT * FROM t1 FULL OUTER JOIN t2 ON t1.id = t2.id;", "Does MySQL support FULL OUTER JOIN natively?"),
    ("Does MySQL support FULL OUTER JOIN natively?", "No. MySQL does not have a native FULL JOIN keyword. Emulate it using LEFT JOIN UNION RIGHT JOIN.", "Intermediate", "Practical", "SELECT * FROM t1 LEFT JOIN t2 ON t1.id = t2.id\nUNION\nSELECT * FROM t1 RIGHT JOIN t2 ON t1.id = t2.id;", "What is a CROSS JOIN?"),
    ("What is a CROSS JOIN (Cartesian Product) in SQL?", "A CROSS JOIN produces the Cartesian product of two tables: every row of table A is paired with every row of table B (total rows = rows(A) * rows(B)).", "Easy", "Concept", "SELECT * FROM sizes CROSS JOIN colors;", "When is CROSS JOIN intentionally useful?"),
    ("When is a CROSS JOIN intentionally useful in business applications?", "Generating combinations (e.g. all product sizes x all colors), or creating calendars/date matrices by cross-joining years with months.", "Intermediate", "Scenario", "", "What is a Self Join in SQL?"),
    ("What is a Self Join and when is it used?", "A Self Join is a regular join where a table is joined with itself using distinct aliases, commonly used for hierarchical data (e.g. employee and their manager).", "Intermediate", "Concept", "SELECT e.name AS employee, m.name AS manager\nFROM employees e\nLEFT JOIN employees m ON e.manager_id = m.id;", "Give an example of a Self Join query."),
    ("Self Join Coding: Write a query to find all employees and the name of their manager.", "SELECT e.name AS emp, m.name AS mgr FROM employees e LEFT JOIN employees m ON e.manager_id = m.id;", "Easy", "Coding", "SELECT e.name AS employee_name, m.name AS manager_name\nFROM employees e\nLEFT JOIN employees m ON e.manager_id = m.id;", "Why use LEFT JOIN instead of INNER JOIN for manager?"),
    ("Why should a Self Join for employee-manager use LEFT JOIN rather than INNER JOIN?", "Because the top-level CEO/Founder has manager_id = NULL. An INNER JOIN would exclude the CEO completely from the results.", "Easy", "Scenario", "", "What is a Natural Join in SQL?"),
    ("What is a NATURAL JOIN and why is it considered dangerous in production?", "NATURAL JOIN joins tables automatically on all columns with identical names. If someone adds a column with the same name (like created_at) to both tables, the join condition silently breaks.", "Intermediate", "Comparison", "", "What is the USING clause in SQL joins?"),
    ("What does the USING(column) clause do in SQL joins?", "Shorthand for ON when both tables share the exact same column name: 'JOIN orders USING (customer_id)' instead of 'ON a.customer_id = b.customer_id'.", "Easy", "Practical", "SELECT * FROM customers JOIN orders USING (customer_id);", "How does USING differ from ON?"),
    ("What happens if you join on a column where both tables have NULL values?", "Rows with NULL do NOT match each other! In SQL, NULL = NULL evaluates to UNKNOWN. Rows with NULL keys are excluded from INNER JOIN.", "Intermediate", "Concept", "", "How do you find rows in Table A that have NO match in Table B (Anti-Join)?"),
    ("How do you find records in Table A that do not exist in Table B using a LEFT JOIN?", "Use LEFT JOIN with WHERE b.id IS NULL: SELECT a.* FROM a LEFT JOIN b ON a.id = b.a_id WHERE b.id IS NULL;.", "Easy", "Coding", "SELECT c.id, c.name\nFROM customers c\nLEFT JOIN orders o ON c.id = o.customer_id\nWHERE o.id IS NULL; -- Customers with NO orders", "What is an Anti-Join?"),
    ("What is an Anti-Join?", "A relational algebra pattern that returns rows from one relation that have NO matching rows in another relation (achieved via LEFT JOIN IS NULL, NOT IN, or NOT EXISTS).", "Intermediate", "Concept", "", "What is a Semi-Join in SQL?"),
    ("What is a Semi-Join?", "A relational pattern that returns rows from table A where at least one match exists in table B, WITHOUT duplicating rows of table A (achieved via EXISTS or IN).", "Intermediate", "Concept", "SELECT * FROM departments d\nWHERE EXISTS (SELECT 1 FROM employees e WHERE e.dept_id = d.id);", "How does a Semi-Join differ from an INNER JOIN?"),
    ("How does a Semi-Join (EXISTS) differ from an INNER JOIN?", "If a department has 100 employees, INNER JOIN duplicates the department row 100 times. A Semi-Join returns each matching department exactly ONCE.", "Intermediate", "Comparison", "", "What is the difference between ON and WHERE in a LEFT JOIN?"),
    ("What is the critical difference between putting a filter condition in the ON clause vs the WHERE clause of a LEFT JOIN?", "Conditions in ON filter the right table BEFORE joining (left table rows are still preserved). Conditions in WHERE filter the final result AFTER joining (drops left rows, converting LEFT JOIN into INNER JOIN!).", "Advanced", "Concept", "-- ON clause: Preserves all users, joins only active orders\nSELECT u.name, o.id\nFROM users u\nLEFT JOIN orders o ON u.id = o.user_id AND o.status = 'active';\n\n-- WHERE clause: Filters out users who have no active orders!\nSELECT u.name, o.id\nFROM users u\nLEFT JOIN orders o ON u.id = o.user_id\nWHERE o.status = 'active';", "Why does WHERE o.status = 'active' turn a LEFT JOIN into an INNER JOIN?"),
    ("Why does 'WHERE o.status = active' turn a LEFT JOIN into an INNER JOIN?", "Because rows without matching orders have o.status = NULL. The WHERE clause tests NULL = 'active' (false) and discards those rows.", "Advanced", "Scenario", "", "Can you join more than two tables in a single query?"),
    ("How do you join three or more tables in SQL?", "Chain JOIN clauses sequentially: SELECT * FROM orders o JOIN customers c ON o.c_id = c.id JOIN order_items oi ON o.id = oi.order_id JOIN products p ON oi.p_id = p.id;.", "Easy", "Practical", "SELECT c.name, p.title\nFROM orders o\nJOIN customers c ON o.customer_id = c.id\nJOIN items i ON o.id = i.order_id\nJOIN products p ON i.product_id = p.id;", "What is the difference between UNION and UNION ALL?"),
    ("What is the difference between UNION and UNION ALL in SQL?", "UNION combines result sets from two queries and removes duplicate rows (requires an internal sort/hash). UNION ALL combines result sets WITHOUT removing duplicates (much faster).", "Easy", "Comparison", "SELECT name FROM employees\nUNION ALL\nSELECT name FROM contractors;", "Why is UNION ALL faster than UNION?"),
    ("Why is UNION ALL significantly faster than UNION?", "UNION ALL does not check for or deduplicate records, avoiding expensive sorting or in-memory hash table deduplication.", "Easy", "Performance", "", "What are the rules for combining queries with UNION?"),
    ("What are the two requirements for queries combined with UNION / UNION ALL?", "1. Each query must have the same number of columns in the SELECT list. 2. The corresponding columns must have compatible data types.", "Easy", "Concept", "", "What does the INTERSECT operator do?"),
    ("What does the INTERSECT operator do in SQL?", "INTERSECT returns only the rows that appear in BOTH query result sets (set intersection).", "Easy", "Concept", "SELECT customer_id FROM online_orders\nINTERSECT\nSELECT customer_id FROM store_orders;", "What does EXCEPT / MINUS operator do?"),
    ("What does the EXCEPT (or MINUS in Oracle) operator do?", "EXCEPT returns rows from the first query that DO NOT appear in the second query (set difference).", "Easy", "Concept", "SELECT product_id FROM all_products\nEXCEPT\nSELECT product_id FROM discontinued_products;", "What is an Equi-Join vs Non-Equi Join?"),
    ("What is the difference between an Equi-Join and a Non-Equi Join?", "Equi-Join uses the equality operator '=' in the join condition. Non-Equi Join uses comparison operators (<, >, BETWEEN, !=) in the join condition.", "Intermediate", "Comparison", "-- Non-equi join:\nSELECT e.name, g.grade\nFROM employees e\nJOIN salary_grades g ON e.salary BETWEEN g.min_sal AND g.max_sal;", "Give an example of a Non-Equi Join."),
    ("Joins MCQ: Which join returns all rows from the left table and matching rows from the right table?", "Option B is correct. LEFT OUTER JOIN preserves all left table records.", "Easy", "MCQ", "", {"A": "INNER JOIN", "B": "LEFT JOIN", "C": "RIGHT JOIN", "D": "CROSS JOIN"}, "B", "What does INNER JOIN return?"),
    ("Joins MCQ: If Table A has 5 rows and Table B has 4 rows, how many rows does 'A CROSS JOIN B' return?", "Option C is correct. 5 * 4 = 20 rows.", "Easy", "MCQ", "", {"A": "5", "B": "9", "C": "20", "D": "1"}, "C", "What is this product called?"),
    ("Joins MCQ: What operator combines two query results and removes duplicate rows?", "Option A is correct. UNION deduplicates; UNION ALL preserves duplicates.", "Easy", "MCQ", "", {"A": "UNION", "B": "UNION ALL", "C": "JOIN", "D": "COMBINE"}, "A", "Which is faster?"),
    ("Joins MCQ: How do you identify records in Table A with no matches in Table B?", "Option D is correct. LEFT JOIN Table B ON A.id = B.a_id WHERE B.id IS NULL.", "Easy", "MCQ", "", {"A": "INNER JOIN WHERE B.id IS NULL", "B": "CROSS JOIN", "C": "FULL JOIN WHERE B.id = A.id", "D": "LEFT JOIN WHERE B.id IS NULL"}, "D", "What is this pattern called?"),
    ("Joins Coding: Find all customers who have never placed an order.", "SELECT c.id, c.name FROM customers c LEFT JOIN orders o ON c.id = o.customer_id WHERE o.id IS NULL;", "Easy", "Coding", "SELECT c.id, c.name\nFROM customers c\nLEFT JOIN orders o ON c.id = o.customer_id\nWHERE o.id IS NULL;", "Can this be written with NOT EXISTS?"),
    ("Joins Coding: Write the previous query using NOT EXISTS.", "SELECT * FROM customers c WHERE NOT EXISTS (SELECT 1 FROM orders o WHERE o.customer_id = c.id);", "Easy", "Coding", "SELECT c.id, c.name\nFROM customers c\nWHERE NOT EXISTS (\n  SELECT 1 FROM orders o WHERE o.customer_id = c.id\n);", "Which is generally preferred by query optimizers?"),
    ("Joins Coding: Fetch all orders along with the customer's name and total order item count.", "SELECT o.id, c.name, COUNT(oi.id) FROM orders o JOIN customers c ON o.customer_id = c.id JOIN order_items oi ON o.id = oi.order_id GROUP BY o.id, c.name;", "Intermediate", "Coding", "SELECT o.id AS order_id, c.name AS customer_name, COUNT(oi.id) AS item_count\nFROM orders o\nJOIN customers c ON o.customer_id = c.id\nJOIN order_items oi ON o.id = oi.order_id\nGROUP BY o.id, c.name;", "What if an order has 0 items?"),
    ("Joins Debugging: A developer wrote: SELECT * FROM users u LEFT JOIN orders o ON u.id = o.user_id WHERE o.amount > 100; but wanted all users. Why did users without orders disappear?", "The condition 'o.amount > 100' in WHERE eliminates rows where o.amount is NULL. Move the condition into the ON clause: ON u.id = o.user_id AND o.amount > 100.", "Intermediate", "Debugging", "-- FIX:\nSELECT * FROM users u\nLEFT JOIN orders o ON u.id = o.user_id AND o.amount > 100;", "Why did the WHERE clause break the outer join?"),
    ("What is a Hash Join in query execution plans?", "An execution algorithm where the database builds an in-memory hash table of the smaller table, then scans the larger table probing for matching hash keys. Ideal for large unsorted datasets.", "Advanced", "Architecture", "", "What is a Nested Loop Join?",),
    ("What is a Nested Loop Join in database internals?", "For each outer table row, the database scans the inner table (ideally using an index) for matches. Highly efficient when the outer table is small and inner table has an indexed join key.", "Advanced", "Architecture", "", "What is a Merge Join (Sort-Merge Join)?",),
    ("What is a Merge Join (Sort-Merge Join)?", "Both tables are sorted by the join key and scanned concurrently in lockstep. Highly efficient when input datasets are already sorted by indexes.", "Advanced", "Architecture", "", "What is an alias clash in SQL joins?",),
    ("What is a column name ambiguity error in SQL joins?", "When both joined tables contain a column with the same name (like 'id'), selecting 'id' throws: 'Column id in field list is ambiguous'. Qualify with table alias: 'u.id'.", "Easy", "Debugging", "-- FIX:\nSELECT u.id AS user_id, o.id AS order_id\nFROM users u\nJOIN orders o ON u.id = o.user_id;", "Why qualify columns?"),
    ("What does a CROSS APPLY / LATERAL JOIN do in SQL?", "A LATERAL join (or CROSS APPLY in SQL Server) allows a subquery in the FROM/JOIN clause to reference columns from preceding tables in the join sequence.", "Advanced", "Concept", "SELECT c.name, o.*\nFROM customers c\nCROSS JOIN LATERAL (\n  SELECT * FROM orders WHERE customer_id = c.id ORDER BY date DESC LIMIT 3\n) o;", "When is LATERAL join useful?"),
    ("How do you find the top 3 most recent orders for EVERY customer?", "Use a LATERAL JOIN (or CROSS APPLY): join each customer with a subquery selecting their 3 most recent orders.", "Advanced", "Coding", "SELECT c.name, recent_orders.id, recent_orders.order_date\nFROM customers c\nCROSS JOIN LATERAL (\n  SELECT id, order_date FROM orders\n  WHERE customer_id = c.id\n  ORDER BY order_date DESC LIMIT 3\n) AS recent_orders;", "What is the equivalent in window functions?"),
    ("What is an inner join on multiple conditions?", "JOIN t2 ON t1.id = t2.t1_id AND t1.tenant_id = t2.tenant_id (essential for multi-tenant database designs).", "Intermediate", "Practical", "JOIN invoices i ON c.id = i.customer_id AND c.country = i.country", "Why is multi-column join condition used?"),
    ("What happens if you omit the ON clause in an INNER JOIN?", "In MySQL, INNER JOIN without ON acts as a CROSS JOIN, generating a Cartesian product. In strict SQL dialects like PostgreSQL, omitting ON produces a syntax error.", "Intermediate", "Concept", "", "What is self join with inequality?",),
    ("Self Join Coding: Find all pairs of employees who work in the same department without pairing an employee with themselves.", "SELECT e1.name, e2.name, e1.dept_id FROM employees e1 JOIN employees e2 ON e1.dept_id = e2.dept_id AND e1.id < e2.id;", "Intermediate", "Coding", "SELECT e1.name AS emp1, e2.name AS emp2, e1.department_id\nFROM employees e1\nJOIN employees e2 ON e1.department_id = e2.department_id AND e1.id < e2.id;", "Why use e1.id < e2.id instead of != ?"),
    ("Why is 'e1.id < e2.id' used instead of 'e1.id != e2.id' in pair matching?", "'!=' produces duplicate reverse pairs (Alice & Bob, and Bob & Alice). '<' ensures each pair is listed exactly once and prevents self-matching.", "Intermediate", "Concept", "", "What is a Star Schema in data warehousing?"),
    ("What is a Star Schema in database design?", "A design where a central Fact table containing quantitative metrics is directly connected to multiple surrounding Dimension tables via foreign keys.", "Intermediate", "Architecture", "", "What is a Snowflake Schema?"),
    ("What is the difference between a Star Schema and a Snowflake Schema?", "In a Star Schema, dimension tables are denormalized. In a Snowflake Schema, dimension tables are normalized into further sub-dimension tables resembling a snowflake.", "Intermediate", "Comparison", "", "What is a Fact table vs Dimension table?"),
    ("What is the difference between a Fact Table and a Dimension Table?", "Fact table: stores numerical business measurements and transactions (sales amount, quantity, timestamps). Dimension table: stores descriptive context attributes (customer name, product category, store location).", "Intermediate", "Comparison", "", "What is data federation in SQL?"),
    ("What is a Foreign Data Wrapper (FDW) in PostgreSQL?", "A feature allowing PostgreSQL to query remote tables in other databases (MySQL, Redis, MongoDB, remote Postgres) using standard SQL queries as if they were local tables.", "Advanced", "Architecture", "", "What is DBLink in MySQL/Oracle?"),
    ("What is a Database Link (DBLink)?", "A database connection definition enabling queries on a local database to access objects on a remote database server.", "Intermediate", "Concept", "", "How does a database handle joining tables with different collations?"),
    ("What causes 'Illegal mix of collations' error in MySQL joins?", "Joining string columns that have different character sets or collations (e.g. utf8mb4_general_ci vs utf8mb4_unicode_ci). Fix by specifying COLLATE in the join condition.", "Intermediate", "Debugging", "ON a.code COLLATE utf8mb4_unicode_ci = b.code", "How do you fix collation mismatch?"),
    ("What is join cardinality?", "The numerical relationship between records in joined tables: 1-to-1, 1-to-Many, or Many-to-Many.", "Easy", "Concept", "", "How is a Many-to-Many relationship implemented in SQL?"),
    ("How do you model a Many-to-Many relationship between Students and Courses?", "Create a Junction / Bridge / Pivot table (student_courses) containing foreign keys referencing both primary keys (student_id, course_id).", "Easy", "Concept", "CREATE TABLE student_courses (\n  student_id INT REFERENCES students(id),\n  course_id INT REFERENCES courses(id),\n  PRIMARY KEY (student_id, course_id)\n);", "What is the primary key of a junction table?"),
    ("What is an outer join on NULLable foreign keys?", "When foreign keys can be NULL, an INNER JOIN silently discards records where FK is NULL. Always use LEFT JOIN if unassigned records must be preserved.", "Easy", "Best Practice", "", "Why should join conditions only contain relationship predicates?",),
    ("Why should business filters be in WHERE rather than ON in an INNER JOIN?", "While ON and WHERE produce identical results in INNER JOIN, placing join keys in ON and business filters in WHERE makes SQL queries much cleaner to read and maintain.", "Easy", "Best Practice", "", "What is an implicit join vs explicit join?"),
    ("What is the difference between an Implicit Join and an Explicit Join?", "Implicit: 'FROM tableA, tableB WHERE tableA.id = tableB.id' (old SQL-89 syntax). Explicit: 'FROM tableA JOIN tableB ON ...' (SQL-92 syntax). Always use Explicit Joins.", "Easy", "Comparison", "-- Implicit (AVOID):\nSELECT * FROM a, b WHERE a.id = b.id;\n-- Explicit (RECOMMENDED):\nSELECT * FROM a JOIN b ON a.id = b.id;", "Why is explicit join preferred?"),
    ("Why is explicit JOIN syntax strongly preferred over implicit comma joins?", "Explicit joins separate join logic from filtering logic, prevent accidental Cartesian products from forgotten WHERE conditions, and support all outer join types cleanly.", "Easy", "Best Practice", "", "Can you join on expressions rather than direct columns?"),
    ("Can a join condition use functions and expressions?", "Yes: ON DATE(a.created_at) = DATE(b.created_at). However, wrapping indexed columns in functions prevents index usage, causing slow full table scans.", "Intermediate", "Performance", "", "How do you optimize an expression join?"),
    ("How do you optimize joins on expressions to maintain index speed?", "Use generated columns (virtual/stored) with an index on the generated column, or store pre-calculated values directly.", "Advanced", "Performance", "", "What is join elimination in SQL query optimizers?"),
    ("What is Join Elimination in database query optimizers?", "An optimization where the database detects that a joined table's columns are never selected and its foreign key constraint guarantees matching rows, removing the join entirely from execution!", "Advanced", "Architecture", "", "When does join elimination occur?")
]

sql_subqueries_adv = [
    # Subqueries, CTEs, Window Functions (50 Qs)
    ("What is a Subquery in SQL?", "A Subquery (inner query / nested query) is a SELECT query nested inside another SQL statement (SELECT, INSERT, UPDATE, or DELETE).", "Easy", "Concept", "SELECT * FROM emp WHERE salary > (SELECT AVG(salary) FROM emp);", "What are the three types of subqueries by location?"),
    ("Where can subqueries be placed in an SQL statement?", "In the WHERE clause (filtering), FROM clause (derived table), and SELECT clause (scalar projection).", "Easy", "Concept", "", "What is a Scalar Subquery?"),
    ("What is a Scalar Subquery?", "A subquery that returns exactly ONE row and ONE column (a single value). It can be used anywhere a scalar literal value is expected.", "Easy", "Concept", "SELECT name, (SELECT MAX(price) FROM products) AS max_p FROM products;", "What happens if a scalar subquery returns multiple rows?"),
    ("What error occurs if a scalar subquery returns more than one row?", "The database throws a runtime error: 'Subquery returned more than 1 value' / 'scalar subquery produced more than one element'.", "Easy", "Debugging", "", "What is a Correlated Subquery?"),
    ("What is a Correlated Subquery and how does it differ from a non-correlated subquery?", "A non-correlated subquery executes once independently of the outer query. A Correlated Subquery references columns from the outer query and executes once for EVERY candidate row processed by the outer query.", "Intermediate", "Comparison", "SELECT e.name, e.salary\nFROM employees e\nWHERE e.salary > (\n  SELECT AVG(salary) FROM employees WHERE department_id = e.department_id\n);", "Why can correlated subqueries be slow on large tables?"),
    ("Why can correlated subqueries cause performance bottlenecks?", "Because they execute row-by-row (O(N) executions). If the outer table has 100,000 rows, the subquery may execute 100,000 times unless optimized or rewritten with a JOIN / Window function.", "Intermediate", "Performance", "", "What is the EXISTS operator in SQL?"),
    ("What does the EXISTS operator do and how does it optimize execution?", "EXISTS tests for the existence of rows in a subquery. It returns TRUE as soon as the first matching row is found and stops scanning immediately (short-circuit evaluation).", "Easy", "Concept", "SELECT * FROM customers c WHERE EXISTS (SELECT 1 FROM orders o WHERE o.customer_id = c.id);", "Why is 'SELECT 1' standard in EXISTS subqueries?"),
    ("Why do developers write 'SELECT 1' inside an EXISTS subquery?", "Because EXISTS only cares whether any matching row exists, not what columns are selected. Writing SELECT 1 makes intent explicit and avoids column overhead.", "Easy", "Best Practice", "WHERE EXISTS (SELECT 1 FROM ...)", "What is the difference between IN and EXISTS?"),
    ("What is the difference between IN and EXISTS?", "IN evaluates all values returned by the subquery into a set and checks membership. EXISTS evaluates conditionally row-by-row and short-circuits. EXISTS handles NULLs safely, whereas NOT IN fails if NULLs exist.", "Intermediate", "Comparison", "", "When is EXISTS faster?"),
    ("What is a Common Table Expression (CTE) and what keyword defines it?", "A CTE is a temporary named result set defined within a single SQL statement using the WITH keyword: WITH cte_name AS (SELECT ...).", "Easy", "Concept", "WITH HighEarners AS (\n  SELECT * FROM employees WHERE salary > 100000\n)\nSELECT department_id, COUNT(*) FROM HighEarners GROUP BY department_id;", "What are the benefits of CTEs over subqueries?"),
    ("What are the advantages of Common Table Expressions (CTEs)?", "1. Greatly improves code readability and modularity. 2. Can be referenced multiple times within the same query. 3. Enables Recursive Queries for hierarchies.", "Easy", "Concept", "", "What is a Recursive CTE in SQL?",),
    ("What is a Recursive CTE and when is it used?", "A CTE that references itself to traverse hierarchical or tree-structured data (organizational charts, bill-of-materials, graph paths).", "Advanced", "Concept", "WITH RECURSIVE OrgChart AS (\n  SELECT id, name, manager_id, 1 AS level FROM employees WHERE manager_id IS NULL\n  UNION ALL\n  SELECT e.id, e.name, e.manager_id, o.level + 1\n  FROM employees e JOIN OrgChart o ON e.manager_id = o.id\n)\nSELECT * FROM OrgChart;", "What are the two parts of a recursive CTE?"),
    ("What are the two parts of a Recursive CTE?", "1. Anchor Member (base query, executes once). 2. Recursive Member (query that joins the CTE with the table, executing iteratively until no new rows are returned).", "Advanced", "Concept", "", "What happens if a recursive CTE has an infinite loop?"),
    ("How do databases prevent infinite loops in recursive CTEs?", "Most engines have safety recursion limits (e.g. MAXRECURSION 100 in SQL Server, max_statement_time in MySQL) and throw an error if exceeded.", "Intermediate", "Concept", "", "What are Window Functions in SQL?",),
    ("What are Window Functions (Analytic Functions) in SQL?", "Window functions perform calculations across a set of table rows related to the current row (a 'window'), WITHOUT collapsing rows like GROUP BY does.", "Intermediate", "Concept", "SELECT name, department, salary,\n  AVG(salary) OVER(PARTITION BY department) AS dept_avg\nFROM employees;", "What is the OVER() clause in window functions?"),
    ("What does the OVER() clause specify in window functions?", "It defines the partition (PARTITION BY) and ordering (ORDER BY) of the row window over which the function operates.", "Easy", "Concept", "OVER (PARTITION BY department_id ORDER BY salary DESC)", "What is the difference between ROW_NUMBER(), RANK(), and DENSE_RANK()?"),
    ("What is the difference between ROW_NUMBER(), RANK(), and DENSE_RANK()?", "ROW_NUMBER(): Assigns unique sequential integers (1, 2, 3, 4) regardless of ties. RANK(): Assigns same rank to ties and skips subsequent ranks (1, 2, 2, 4). DENSE_RANK(): Assigns same rank to ties WITHOUT skipping (1, 2, 2, 3).", "Intermediate", "Comparison", "-- If salaries are: 100, 90, 90, 80\n-- ROW_NUMBER: 1, 2, 3, 4\n-- RANK:       1, 2, 2, 4\n-- DENSE_RANK: 1, 2, 2, 3", "Which function should be used to find top 3 distinct salaries?"),
    ("Which window function should you use to find the top 3 highest unique salaries?", "DENSE_RANK(), because it does not skip ranks when duplicate salaries tie.", "Intermediate", "Best Practice", "", "Why does DENSE_RANK not skip?"),
    ("Window Functions Coding: Find the top 2 highest paid employees in every department.", "WITH ranked AS (SELECT *, DENSE_RANK() OVER(PARTITION BY department_id ORDER BY salary DESC) as r FROM employees) SELECT * FROM ranked WHERE r <= 2;", "Intermediate", "Coding", "WITH RankedEmployees AS (\n  SELECT id, name, department_id, salary,\n    DENSE_RANK() OVER (PARTITION BY department_id ORDER BY salary DESC) AS sal_rank\n  FROM employees\n)\nSELECT * FROM RankedEmployees\nWHERE sal_rank <= 2;", "Why must window function filtering be wrapped in a CTE or subquery?"),
    ("Why can't you use window functions directly inside a WHERE clause?", "Because Window functions are computed in step 6 of query execution, AFTER the WHERE clause (step 2) has already executed. Wrap in a CTE or subquery.", "Intermediate", "Concept", "-- WRONG: WHERE ROW_NUMBER() OVER (...) <= 2\n-- CORRECT: Wrap in CTE then filter in outer query", "What does LEAD() function do?"),
    ("What does the LEAD(column, [offset], [default]) window function do?", "LEAD accesses data from a subsequent (following) row at a specified offset without needing a self-join (e.g. comparing this month's revenue with next month).", "Intermediate", "Concept", "SELECT month, revenue,\n  LEAD(revenue, 1) OVER (ORDER BY month) AS next_month_revenue\nFROM monthly_sales;", "What does LAG() function do?"),
    ("What does the LAG(column, [offset], [default]) window function do?", "LAG accesses data from a preceding (previous) row at a specified offset (e.g. calculating day-over-day growth: today_sales - LAG(today_sales, 1)).", "Intermediate", "Concept", "SELECT date, sales,\n  sales - LAG(sales, 1) OVER (ORDER BY date) AS daily_growth\nFROM daily_sales;", "How do you calculate year-over-year growth with LAG?"),
    ("Window Coding: Calculate month-over-month revenue growth percentage.", "SELECT month, revenue, ROUND(100.0 * (revenue - LAG(revenue) OVER(ORDER BY month)) / LAG(revenue) OVER(ORDER BY month), 2) AS growth_pct FROM sales;", "Intermediate", "Coding", "SELECT month, revenue,\n  ROUND(\n    100.0 * (revenue - LAG(revenue) OVER (ORDER BY month)) /\n    LAG(revenue) OVER (ORDER BY month),\n    2\n  ) AS mom_growth_pct\nFROM monthly_revenue;", "What does FIRST_VALUE() and LAST_VALUE() do?"),
    ("What do FIRST_VALUE() and LAST_VALUE() window functions do?", "FIRST_VALUE returns the first value in an ordered partition. LAST_VALUE returns the last value in the window frame.", "Intermediate", "Concept", "FIRST_VALUE(salary) OVER (PARTITION BY dept ORDER BY salary DESC)", "What is window frame (ROWS BETWEEN)?"),
    ("What does 'ROWS BETWEEN 2 PRECEDING AND CURRENT ROW' mean in window frames?", "It defines a sliding calculation window including the current row and the two rows immediately before it (used for 3-day moving averages).", "Advanced", "Concept", "AVG(sales) OVER (\n  ORDER BY date\n  ROWS BETWEEN 2 PRECEDING AND CURRENT ROW\n) AS three_day_moving_avg", "Give an example of a moving average query."),
    ("Window Coding: Write a query to compute a 7-day moving average of daily active users.", "SELECT date, AVG(dau) OVER (ORDER BY date ROWS BETWEEN 6 PRECEDING AND CURRENT ROW) AS moving_avg_7d FROM daily_metrics;", "Intermediate", "Coding", "SELECT date, active_users,\n  AVG(active_users) OVER (\n    ORDER BY date\n    ROWS BETWEEN 6 PRECEDING AND CURRENT ROW\n  ) AS moving_avg_7d\nFROM daily_metrics;", "What is NTILE(n) window function?"),
    ("What does the NTILE(n) window function do in SQL?", "NTILE divides an ordered partition into n approximately equal groups (buckets), assigning a bucket number from 1 to n (e.g. NTILE(4) creates quartiles).", "Intermediate", "Concept", "SELECT name, salary, NTILE(4) OVER (ORDER BY salary DESC) AS quartile FROM employees;", "When is NTILE useful?"),
    ("What is the difference between ROWS and RANGE in window frames?", "ROWS treats duplicates as individual distinct physical lines. RANGE treats rows with identical ORDER BY values as a single peer group logical range.", "Advanced", "Comparison", "", "What is the ANY / SOME operator in SQL subqueries?"),
    ("What does the '> ANY (subquery)' condition mean in SQL?", "It evaluates to TRUE if the value is greater than AT LEAST ONE value returned by the subquery (equivalent to > MIN(subquery)).", "Intermediate", "Concept", "WHERE salary > ANY (SELECT salary FROM employees WHERE dept_id = 3)", "What does the ALL operator do?"),
    ("What does the '> ALL (subquery)' condition mean in SQL?", "It evaluates to TRUE if the value is greater than EVERY single value returned by the subquery (equivalent to > MAX(subquery)).", "Intermediate", "Concept", "WHERE salary > ALL (SELECT salary FROM employees WHERE dept_id = 3)", "What is a derived table?"),
    ("What is a Derived Table in SQL?", "An unnamed subquery in the FROM clause that creates a temporary virtual table for the outer query; it MUST be given an alias in most RDBMS.", "Easy", "Concept", "SELECT * FROM (SELECT id, name FROM users) AS u;", "Why do derived tables require aliases in MySQL?"),
    ("Why does MySQL throw an error if a subquery in FROM has no alias?", "MySQL syntax strictly requires: 'Every derived table must have its own alias' so columns can be unambiguously referenced.", "Easy", "Debugging", "-- WRONG: SELECT * FROM (SELECT 1);\n-- CORRECT: SELECT * FROM (SELECT 1) AS t;", "Subqueries MCQ: What is the difference between RANK() and DENSE_RANK() when ties occur?"),
    ("Subqueries MCQ: If scores are 90, 90, 80, what ranks does DENSE_RANK() assign?", "Option B is correct. 1, 1, 2 (no ranks skipped).", "Easy", "MCQ", "", {"A": "1, 2, 3", "B": "1, 1, 2", "C": "1, 1, 3", "D": "1, 2, 2"}, "B", "What would RANK() assign?"),
    ("Subqueries MCQ: Which window function retrieves the value from the preceding row without a self-join?", "Option A is correct. LAG() accesses prior rows.", "Easy", "MCQ", "", {"A": "LAG()", "B": "LEAD()", "C": "PREV()", "D": "PRIOR()"}, "A", "What accesses subsequent rows?"),
    ("Subqueries MCQ: What keyword introduces a Common Table Expression?", "Option C is correct. WITH introduces CTEs.", "Easy", "MCQ", "", {"A": "AS", "B": "CTE", "C": "WITH", "D": "DECLARE"}, "C", "Can multiple CTEs be defined with one WITH?"),
    ("Subqueries MCQ: Which operator checks if a subquery returns ANY rows with short-circuit evaluation?", "Option D is correct. EXISTS short-circuits on first match.", "Easy", "MCQ", "", {"A": "IN", "B": "ANY", "C": "ALL", "D": "EXISTS"}, "D", "What does it return if match found?"),
    ("Subqueries Coding: Write a query to find all employees whose salary is above the average salary of their own department.", "SELECT * FROM employees e WHERE salary > (SELECT AVG(salary) FROM employees WHERE department_id = e.department_id);", "Intermediate", "Coding", "SELECT e.id, e.name, e.salary, e.department_id\nFROM employees e\nWHERE e.salary > (\n  SELECT AVG(salary)\n  FROM employees\n  WHERE department_id = e.department_id\n);", "How can this be written with a window function?"),
    ("Window Coding: Write the same above-average query using a window function in a CTE.", "WITH dept_avgs AS (SELECT *, AVG(salary) OVER(PARTITION BY department_id) as avg_sal FROM employees) SELECT * FROM dept_avgs WHERE salary > avg_sal;", "Intermediate", "Coding", "WITH DeptAverages AS (\n  SELECT id, name, department_id, salary,\n    AVG(salary) OVER (PARTITION BY department_id) AS dept_avg\n  FROM employees\n)\nSELECT id, name, department_id, salary, dept_avg\nFROM DeptAverages\nWHERE salary > dept_avg;", "Why is the window function approach faster?"),
    ("Subqueries Debugging: Query: 'SELECT name FROM users WHERE id NOT IN (SELECT manager_id FROM employees);' returns 0 rows. Why?", "If any employee has manager_id = NULL, NOT IN returns an empty set. Fix by adding 'WHERE manager_id IS NOT NULL' or using NOT EXISTS.", "Intermediate", "Debugging", "-- FIX:\nSELECT name FROM users\nWHERE id NOT IN (\n  SELECT manager_id FROM employees WHERE manager_id IS NOT NULL\n);", "Why does NULL break NOT IN?"),
    ("What is the Cumulative Distribution function CUME_DIST()?", "CUME_DIST calculates the relative rank of a value in a partition (percentage of rows with values <= current row). Range is 0 < CUME_DIST <= 1.", "Advanced", "Concept", "SELECT name, salary, CUME_DIST() OVER (ORDER BY salary) FROM emp;", "What is PERCENT_RANK()?"),
    ("What does PERCENT_RANK() calculate in SQL?", "PERCENT_RANK evaluates relative rank as a percentage from 0.0 to 1.0: (rank - 1) / (total_rows - 1).", "Advanced", "Concept", "SELECT name, salary, PERCENT_RANK() OVER (ORDER BY salary) FROM emp;", "How does it differ from CUME_DIST?"),
    ("What is running total in SQL and how do you calculate it?", "A running total accumulates values row-by-row. Calculate using: SUM(amount) OVER (ORDER BY transaction_date).", "Easy", "Coding", "SELECT date, amount,\n  SUM(amount) OVER (ORDER BY date) AS running_total\nFROM transactions;", "How do you calculate running total per customer?"),
    ("Window Coding: Calculate a running total of deposits partitioned by customer account.", "SELECT account_id, date, amount, SUM(amount) OVER (PARTITION BY account_id ORDER BY date) AS balance FROM transactions;", "Easy", "Coding", "SELECT account_id, transaction_date, amount,\n  SUM(amount) OVER (\n    PARTITION BY account_id\n    ORDER BY transaction_date\n  ) AS account_running_balance\nFROM transactions;", "What happens if ORDER BY is omitted in the OVER clause?"),
    ("What happens if ORDER BY is omitted from 'SUM(amount) OVER ()'?", "Without ORDER BY, the window frame spans the ENTIRE partition, calculating the overall grand total rather than a progressive running sum.", "Intermediate", "Concept", "SELECT amount, SUM(amount) OVER () AS grand_total FROM sales;", "Why does adding ORDER BY change it to a running sum?"),
    ("Why does adding ORDER BY change SUM() OVER() into a running sum?", "By default, adding ORDER BY implies the window frame 'RANGE BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW'.", "Advanced", "Concept", "", "What is the QUALIFY clause in Snowflake/BigQuery?",),
    ("What does the QUALIFY clause do in modern SQL dialects (Snowflake, BigQuery, Databricks)?", "QUALIFY filters the results of window functions directly at the end of the query without requiring an enclosing CTE or subquery.", "Intermediate", "Practical", "SELECT name, department, salary\nFROM employees\nQUALIFY ROW_NUMBER() OVER (PARTITION BY department ORDER BY salary DESC) = 1;", "Is QUALIFY standard ANSI SQL?"),
    ("What is an inline view vs a stored view?", "Inline view: a subquery in the FROM clause of a single statement. Stored view: a named query saved in the database catalog (CREATE VIEW view_name AS ...).", "Easy", "Comparison", "", "What is a Materialized View?",),
    ("What is a Materialized View and how does it differ from a standard View?", "A standard View is a saved query run dynamically on demand. A Materialized View executes once and physically saves the resulting data to disk, updated via REFRESH MATERIALIZED VIEW.", "Intermediate", "Comparison", "CREATE MATERIALIZED VIEW monthly_sales_mv AS SELECT ...;", "When should you use a Materialized View?"),
    ("When should Materialized Views be used?", "For expensive, slow analytical aggregation queries on large tables where real-time freshness is not required and data can be refreshed periodically.", "Intermediate", "Architecture", "", "What is the WITH CHECK OPTION on updatable SQL views?"),
    ("What does 'WITH CHECK OPTION' do on an updatable View?", "It prevents any INSERT or UPDATE through the view from setting values that would violate the view's WHERE condition and cause the row to disappear from the view.", "Intermediate", "Concept", "CREATE VIEW v_active AS SELECT * FROM users WHERE active = true WITH CHECK OPTION;", "What happens if you try to insert active=false?")
]

sql_design_perf = [
    # Database Design, Normalization, Indexing & ACID (50 Qs)
    ("What is Database Normalization and why is it performed?", "Normalization is the systematic process of organizing database tables to eliminate data redundancy, prevent update anomalies, and ensure data integrity.", "Easy", "Concept", "", "What are the three main types of update anomalies?"),
    ("What are Insertion, Update, and Deletion Anomalies?", "Insertion Anomaly: Cannot record data without adding unrelated data. Update Anomaly: Inconsistent data when editing duplicate values in multiple places. Deletion Anomaly: Unintentionally losing other data when deleting a record.", "Intermediate", "Concept", "", "What is First Normal Form (1NF)?"),
    ("What are the requirements for First Normal Form (1NF)?", "1. Each column must hold atomic (indivisible) values (no arrays or comma-separated lists). 2. Each record must have a unique identifier (Primary Key). 3. No repeating groups of columns.", "Easy", "Concept", "-- Violates 1NF: phone = '123-456, 789-012'\n-- 1NF Compliant: separate rows for each phone", "What is Second Normal Form (2NF)?"),
    ("What are the requirements for Second Normal Form (2NF)?", "1. Table must be in 1NF. 2. All non-key attributes must be fully functionally dependent on the ENTIRE primary key (no partial dependencies on part of a composite primary key).", "Intermediate", "Concept", "", "What is Third Normal Form (3NF)?"),
    ("What are the requirements for Third Normal Form (3NF)?", "1. Table must be in 2NF. 2. No transitive dependencies: non-key attributes must NOT depend on other non-key attributes (every column must depend only on the primary key).", "Intermediate", "Concept", "-- Violates 3NF: emp_id -> dept_id -> dept_name (dept_name depends on dept_id, not emp_id)", "What is BCNF (Boyce-Codd Normal Form)?"),
    ("What is Boyce-Codd Normal Form (BCNF)?", "A stricter version of 3NF where every functional determinant must be a candidate key (for every X -> Y, X must be a super key).", "Advanced", "Concept", "", "What is Denormalization and when is it justified?"),
    ("What is Denormalization and why is it used in production systems?", "Deliberately introducing controlled redundancy into a normalized schema to reduce expensive joins and improve read performance in read-heavy applications.", "Intermediate", "Concept", "", "What are the risks of Denormalization?",),
    ("What are the major trade-offs of Denormalization?", "Faster read queries, but slower writes, increased storage consumption, and higher risk of data inconsistency when updating duplicate fields.", "Intermediate", "Comparison", "", "What is an Index in SQL and how does it work?"),
    ("What is a Database Index and what data structure is most commonly used?", "An index is a lookup data structure that allows the database engine to find specific rows in O(log N) time rather than scanning every row (O(N) full table scan). Most commonly implemented as B-Trees.", "Easy", "Concept", "CREATE INDEX idx_users_email ON users(email);", "What is the trade-off of adding indexes?"),
    ("What are the drawbacks and costs of adding indexes?", "Indexes consume additional disk space and slow down write operations (INSERT, UPDATE, DELETE) because every index must be updated on every write.", "Easy", "Best Practice", "", "What is a Clustered Index vs a Non-Clustered Index?"),
    ("What is the difference between a Clustered Index and a Non-Clustered (Secondary) Index?", "Clustered Index: Determines the physical storage order of data rows on disk (only ONE clustered index per table, typically the Primary Key). Non-Clustered Index: A separate structure with pointers/keys pointing back to the physical data rows.", "Intermediate", "Comparison", "", "Why can a table have only ONE Clustered Index?"),
    ("Why can a table have only one clustered index?", "Because physical data rows can only be sorted and stored on disk in one single order.", "Easy", "Concept", "", "What is a Composite (Compound) Index?"),
    ("What is a Composite Index in SQL?", "An index created on two or more columns together: CREATE INDEX idx_emp_dept_sal ON employees(department_id, salary);.", "Easy", "Concept", "CREATE INDEX idx_name ON users(last_name, first_name);", "What is the Leftmost Prefix Rule in composite indexes?"),
    ("What is the Leftmost Prefix Rule in composite indexes?", "A composite index on (A, B, C) can speed up queries filtering on (A), (A, B), or (A, B, C), but CANNOT be used if query filters only on (B) or (C) without (A).", "Intermediate", "Concept", "-- Index: (last_name, first_name)\n-- USES index: WHERE last_name = 'Smith'\n-- DOES NOT use index: WHERE first_name = 'John'", "Why does the order of columns in a composite index matter?"),
    ("Why does column order in a composite index matter?", "B-Trees sort data first by the first column, then by the second within matching values of the first. Searching by the second column alone requires a full index scan.", "Intermediate", "Concept", "", "What is a Covering Index?"),
    ("What is a Covering Index in SQL?", "An index that contains ALL the columns requested by a query (both WHERE and SELECT columns), allowing the database to return results purely from index memory without touching disk table pages.", "Advanced", "Performance", "CREATE INDEX idx_covering ON users(email, first_name, last_name);", "What is Index Selectivity?"),
    ("What is Index Selectivity and why does it determine whether an index is used?", "Selectivity is the ratio of distinct values to total rows. High selectivity (unique email, 99% distinct) makes indexes extremely efficient. Low selectivity (gender, boolean status) causes optimizer to prefer full table scan.", "Intermediate", "Concept", "", "What is the EXPLAIN / EXPLAIN ANALYZE command?"),
    ("What does EXPLAIN (or EXPLAIN ANALYZE) do in SQL?", "EXPLAIN displays the execution plan chosen by the query optimizer (showing table scans, index lookups, join types, and estimated row costs). ANALYZE actually executes the query and shows real runtime stats.", "Easy", "Practical", "EXPLAIN ANALYZE SELECT * FROM users WHERE email = 'test@example.com';", "What is a Full Table Scan (Seq Scan)?"),
    ("What is a Full Table Scan (Sequential Scan)?", "The database reads every single data page on disk from start to finish. Essential for small tables or when fetching >20-30% of all rows, but disastrous for large tables with targeted lookups.", "Easy", "Concept", "type: ALL (MySQL) / Seq Scan (PostgreSQL)", "Name three common causes of index invalidation in queries."),
    ("What query patterns prevent an index from being used (SARGability)?", "1. Wrapping column in a function: WHERE YEAR(created_at) = 2026. 2. Leading wildcard: WHERE name LIKE '%son'. 3. Implicit type conversion: WHERE varchar_col = 123. 4. Doing arithmetic on column: WHERE age + 1 > 18.", "Intermediate", "Performance", "-- BAD: WHERE LOWER(email) = 'a@b.com'\n-- GOOD: WHERE email = 'a@b.com' (with case-insensitive collation)", "How do you rewrite 'WHERE YEAR(created_at) = 2026' to use an index?"),
    ("How do you rewrite 'WHERE YEAR(created_at) = 2026' to allow index usage?", "Use a date range: WHERE created_at >= '2026-01-01' AND created_at < '2027-01-01'.", "Intermediate", "Coding", "-- Index-friendly range query:\nWHERE created_at >= '2026-01-01 00:00:00'\n  AND created_at < '2027-01-01 00:00:00'", "What is a Partial / Filtered Index?"),
    ("What is a Partial Index (Filtered Index)?", "An index built over a subset of rows satisfying a WHERE condition (e.g. index only active users), saving disk space and speeding up targeted queries.", "Intermediate", "Concept", "CREATE INDEX idx_active_users ON users(email) WHERE is_active = true;", "What are ACID properties in database transactions?"),
    ("What do the letters in ACID stand for?", "Atomicity, Consistency, Isolation, and Durability. They guarantee database reliability in the face of errors and concurrent access.", "Easy", "Concept", "", "Explain Atomicity in ACID."),
    ("What does Atomicity mean in ACID?", "'All or Nothing'. All operations within a transaction must either complete successfully together, or the entire transaction is rolled back leaving the database unchanged.", "Easy", "Concept", "BEGIN;\nUPDATE account SET balance = balance - 100 WHERE id = 1;\nUPDATE account SET balance = balance + 100 WHERE id = 2;\nCOMMIT;", "Explain Consistency in ACID."),
    ("What does Consistency mean in ACID?", "A transaction must transition the database from one valid state to another valid state, preserving all constraints, foreign keys, triggers, and rules.", "Easy", "Concept", "", "Explain Isolation in ACID."),
    ("What does Isolation mean in ACID?", "Concurrent transactions execute independently without interfering with each other; intermediate uncommitted states of one transaction are hidden from other transactions.", "Easy", "Concept", "", "Explain Durability in ACID."),
    ("What does Durability mean in ACID?", "Once a transaction is committed, its changes are permanently recorded in non-volatile storage (WAL / redo logs) and will survive server crashes or power failures.", "Easy", "Concept", "", "What are the 4 standard Transaction Isolation Levels?"),
    ("What are the 4 ANSI SQL Transaction Isolation Levels from lowest to highest?", "1. Read Uncommitted. 2. Read Committed. 3. Repeatable Read. 4. Serializable.", "Intermediate", "Concept", "SET TRANSACTION ISOLATION LEVEL REPEATABLE READ;", "What is a Dirty Read?"),
    ("What is a Dirty Read in database transactions?", "Transaction A reads data modified by Transaction B that has NOT yet been committed. If B rolls back, A read data that never truly existed.", "Intermediate", "Concept", "", "What is a Non-Repeatable Read?"),
    ("What is a Non-Repeatable Read?", "Transaction A reads a row, Transaction B updates or deletes that row and commits, and Transaction A re-reads the row obtaining different data.", "Intermediate", "Concept", "", "What is a Phantom Read?"),
    ("What is a Phantom Read in database transactions?", "Transaction A runs a query with a range condition (e.g. salary > 50000), Transaction B inserts a new row matching that range and commits, and Transaction A re-runs the query seeing a new 'phantom' row.", "Intermediate", "Concept", "", "Which isolation level prevents Dirty Reads?"),
    ("Which isolation level prevents Dirty Reads?", "Read Committed (and higher). It ensures a query only reads data that has already been committed.", "Easy", "Concept", "", "What is the default isolation level in PostgreSQL and MySQL?"),
    ("What is the default isolation level in MySQL vs PostgreSQL?", "MySQL InnoDB defaults to REPEATABLE READ. PostgreSQL defaults to READ COMMITTED.", "Intermediate", "Comparison", "", "What is a Deadlock in SQL and how does the engine resolve it?"),
    ("What is a Deadlock in relational databases?", "A circular dependency where Transaction 1 holds a lock on resource A and waits for B, while Transaction 2 holds a lock on resource B and waits for A. Neither can proceed.", "Intermediate", "Concept", "", "How does the database resolve a Deadlock?"),
    ("How does an RDBMS resolve deadlocks?", "The engine's deadlock detection algorithm detects the circular wait, chooses one transaction as the 'victim', forcefully aborts/rolls it back with a deadlock error, allowing the other to finish.", "Intermediate", "Concept", "", "How can developers prevent deadlocks in application code?"),
    ("What is the best way to prevent deadlocks in multi-statement transactions?", "Always access and lock tables/rows in the EXACT SAME consistent order across all application transactions.", "Intermediate", "Best Practice", "-- Both transactions update user 1 before user 2, never in opposite order", "What is Pessimistic vs Optimistic Locking?"),
    ("What is the difference between Pessimistic and Optimistic Locking?", "Pessimistic Locking: Acquires locks upfront (SELECT ... FOR UPDATE) assuming conflicts will happen, blocking other readers/writers. Optimistic Locking: Assumes no conflicts, checks a 'version' column at commit time (WHERE id = 1 AND version = 5), failing if version changed.", "Intermediate", "Comparison", "SELECT * FROM tickets WHERE id = 10 FOR UPDATE; -- Pessimistic\nUPDATE tickets SET seat = '1A', version = version + 1 WHERE id = 10 AND version = 2; -- Optimistic", "When should you use Optimistic Locking?"),
    ("When should Optimistic Locking be used over Pessimistic Locking?", "In web applications with high concurrency and low contention (e.g. e-commerce checkouts) where long-lived database locks would destroy server throughput.", "Intermediate", "Scenario", "", "What does 'SELECT ... FOR UPDATE' do in SQL?",),
    ("What does 'SELECT ... FOR UPDATE' do?", "It locks the selected rows with an exclusive write lock until the transaction commits or rolls back, preventing other transactions from updating, locking, or deleting those rows.", "Intermediate", "Practical", "BEGIN;\nSELECT balance FROM accounts WHERE id = 1 FOR UPDATE;\n-- Now safe to compute and update balance\nUPDATE accounts SET balance = balance - 50 WHERE id = 1;\nCOMMIT;", "What does SKIP LOCKED do?"),
    ("What does 'SELECT ... FOR UPDATE SKIP LOCKED' do in job queues?", "It locks available rows and skips any rows currently locked by other concurrent worker transactions, enabling lock-free high-throughput background job processing.", "Advanced", "Practical", "SELECT * FROM jobs WHERE status = 'pending' LIMIT 1 FOR UPDATE SKIP LOCKED;", "Why is SKIP LOCKED ideal for queue systems?"),
    ("Performance MCQ: What command displays the query optimizer's execution plan?", "Option B is correct. EXPLAIN shows the execution plan.", "Easy", "MCQ", "", {"A": "SHOW QUERY", "B": "EXPLAIN", "C": "ANALYZE QUERY", "D": "DESCRIBE PLAN"}, "B", "What does EXPLAIN ANALYZE do?"),
    ("ACID MCQ: Which property guarantees that once a transaction commits, its data survives server crashes?", "Option D is correct. Durability guarantees persistence.", "Easy", "MCQ", "", {"A": "Atomicity", "B": "Consistency", "C": "Isolation", "D": "Durability"}, "D", "What does Atomicity guarantee?"),
    ("Isolation MCQ: What phenomenon occurs when Transaction A reads uncommitted data from Transaction B?", "Option A is correct. Dirty Read occurs on uncommitted data.", "Easy", "MCQ", "", {"A": "Dirty Read", "B": "Non-Repeatable Read", "C": "Phantom Read", "D": "Lost Update"}, "A", "Which isolation level prevents it?"),
    ("Indexing MCQ: Which column is best suited for an index based on high selectivity?", "Option C is correct. Email address has high uniqueness and selectivity.", "Easy", "MCQ", "", {"A": "Gender (M/F)", "B": "Active status (true/false)", "C": "Email address", "D": "Country"}, "C", "Why is gender poor for indexing?"),
    ("Performance Debugging: A query 'SELECT * FROM users WHERE email LIKE %gmail.com' is extremely slow despite an index on email. Why?", "The leading wildcard '%' prevents the B-tree index from seeking from the root node, forcing a full table scan. B-trees only support prefix searches ('john%').", "Intermediate", "Debugging", "-- Full table scan:\nWHERE email LIKE '%gmail.com'\n-- Index seek supported:\nWHERE email LIKE 'john%'", "How do you do fast suffix search?"),
    ("What is Database Sharding in horizontal scaling?", "Partitioning a large database horizontally across multiple physical server nodes, where each shard holds a subset of rows based on a shard key.", "Intermediate", "Architecture", "", "What is Database Replication (Primary-Replica)?"),
    ("What is Primary-Replica (Master-Slave) database replication?", "The Primary node handles all write operations (INSERT, UPDATE, DELETE) and streams changes to read-only Replica nodes that serve read traffic.", "Easy", "Architecture", "", "What is Replication Lag in read replicas?"),
    ("What is Replication Lag and what user problem can it cause?", "The delay between a write committing on the Primary and appearing on the Replica. If a user posts a comment and immediately refreshes, reading from a lagging replica might show the comment missing ('read-your-own-writes' issue).", "Intermediate", "Scenario", "", "What is connection pooling in database clients?",),
    ("What is Connection Pooling and why is it essential in Node.js applications?", "Opening a new TCP/database connection per HTTP request is slow and exhausts database connections. A connection pool keeps a pool of reusable open connections ready for queries.", "Easy", "Performance", "const pool = new Pool({ max: 20 });\nconst client = await pool.connect();", "What happens if all pool connections are in use?")
]
